    [6365] = {
        achievementId = 6365,
        name = "Zen Master Cook",
        source = "Zen Master Cook",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Level the Pandaria cooking skill rather than another expansion's cooking.",
        acquisition = "Difficulty: Medium - Level the Pandaria cooking skill rather than another expansion's cooking.\n\n1. Visit Sungshin Ironpaw at Halfhill Market. Learn Pandaria Cooking and her starter recipes. Complete So You Want to Be a Chef... by making five Sliced Peaches, then Ready for Greatness by making five Rice Pudding when offered.\n\n2. Use orange or yellow Pandaria recipes and return for new training as your skill rises. Vendor ingredients cover the starter foods; fish, meats and farm vegetables supply later recipes. Train one of the six Ways when available rather than repeatedly making grey starter food.\n\n3. Reach 75 earned skill points in Pandaria Cooking. Another expansion's cooking level does not replace this. Maxing all six Ways is the separate Master of Pandaren Cooking achievement; inspect those individual skill bars if pursuing both.",
        stepCount = 3,
        waypoints = { { mapID = 376, x = 0.536, y = 0.512, step = 1, label = "Sungshin Ironpaw - Halfhill cooking introductions" } },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6365",
        sourceURL = "https://www.wowhead.com/achievement=6365#comments",
        reviewedAt = "2026-11-13",
    },
    [6366] = {
        achievementId = 6366,
        name = "Shado-Pan",
        source = "Shado-Pan",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Build a specific Pandaria faction to Exalted through quests or reputation items.",
        acquisition = "Difficulty: Medium - Build a specific Pandaria faction to Exalted through quests or reputation items.\n\n1. Start at Shado-Pan Garrison. Take the rotating garrison dailies and choose a companion for the assigned island/camp. Golden Lotus Revered is no longer an access requirement.\n\n2. Complete the assigned kills, rescues or special-item objectives and return to the garrison. Stolen Shado-Pan Insignias from Zandalari rares provide repeatable reputation without waiting for each daily rotation.\n\n3. At Revered buy and USE the faction's Grand Commendation from Rushi the Fox at 48.8,70.6 before earning the remaining reputation. The item unlocks increased future gains; merely carrying it does nothing.\n\n4. During Pandaria Timewalking, check Mistweaver Xia on Timeless Isle for this faction's commendations as an alternative. Use them on the character whose reputation you are raising. Continue to EXALTED and verify this achievement; buying a mount is unnecessary for the reputation criterion.",
        stepCount = 4,
        waypoints = {
            { mapID = 388, x = 0.49, y = 0.705, step = 1, label = "Shado-Pan Garrison" },
            { mapID = 554, x = 0.43, y = 0.552, step = 4, label = "Mistweaver Xia - Pandaria Timewalking only" },
        },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6366",
        sourceURL = "https://www.wowhead.com/achievement=6366#comments",
        reviewedAt = "2026-11-13",
    },
    [6394] = {
        achievementId = 6394,
        name = "Rattle No More",
        source = "Rattle No More",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "A quick Heroic boss kill avoids the stacking mechanic.",
        acquisition = "Difficulty: Easy - A quick Heroic boss kill avoids the stacking mechanic.\n\n1. Enter the Pandaria version of Scholomance on Heroic at Caer Darrow in Western Plaguelands. Clear through Jandice Barov to Rattlegore; use the current dungeon rather than the separately unlocked old Scholomance.\n\n2. Kill Rattlegore before Rusting exceeds five stacks. A high-level character can burst him immediately. If fighting at a scaled level, kite him while stacks expire or alternate taunts between two players; pick up Bone Armor for Bone Spike.\n\n3. Check credit after his death. The stack cap applies throughout the fight; allowing six and waiting for them to disappear does not repair the attempt.",
        stepCount = 3,
        waypoints = { { mapID = 22, x = 0.69, y = 0.73, step = 1, label = "Caer Darrow - current Heroic Scholomance" } },
        sources = {
            "https://www.wowhead.com/achievement=6394#comments:id=1722502",
