        reviewedAt = "2026-11-13",
    },
    [6396] = {
        achievementId = 6396,
        name = "Sanguinarian",
        source = "Sanguinarian",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Preserve enough carvers and wait for each stack transfer.",
        acquisition = "Difficulty: Medium - Preserve enough carvers and wait for each stack transfer.\n\n1. Enter current Scholomance on Heroic and defeat Rattlegore. In the next room, the Butcher's Sanctum, preserve the Krastinovian Carvers. Remove damage shields, cleave, damaging pets and automatic area attacks.\n\n2. Gather the room's carvers into one tight group. Kill ONE with a single-target attack, then pause and inspect the survivors' Boiling Bloodthirst buff. Dead carvers transfer stacks to nearby living carvers; killing the whole group together prevents this.\n\n3. Keep killing one carver at a time, allowing transfers to resolve after every kill. Leave the highest-stack survivor alive until its buff reaches 99, then kill that carver for the achievement. Do not spend the room's carvers on unrelated kills first.",
        stepCount = 3,
        waypoints = { { mapID = 22, x = 0.69, y = 0.73, step = 1, label = "Heroic Scholomance - carvers after Rattlegore" } },
