    [6541] = {
        achievementId = 6541,
        name = "Loremaster of Pandaria",
        source = "Loremaster of Pandaria",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Complete the six zone story achievements, including their optional-looking local branches.",
        acquisition = "Difficulty: Hard - Complete the six zone story achievements, including their optional-looking local branches.\n\n1. Complete Upjade Complete on either faction, then Rally the Valley and Mighty Roamin' Krasaranger. Their separate chapter guides include the faction landing, item-started lagoon treasure and independent local hubs.\n\n2. Complete Slum It in the Summit, One Steppe Forward, Two Steppes Back and Dread Haste Makes Dread Waste. Follow the individual story routes for the next quest and chapter hand-ins.\n\n3. Use the six achievements as your checklist. Account-wide zone credit can combine characters and factions; it does not require replaying all six on one character. Reputation dailies, Landfall, Isle of Thunder and Timeless Isle are separate from this original six-zone meta.",
        stepCount = 3,
        waypoints = {
            { mapID = 371, x = 0.462, y = 0.9620000000000001, step = 1, label = "Jade Forest" },
