    [6543] = {
        achievementId = 6543,
        name = "The August Celestials",
        source = "The August Celestials",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Build a specific Pandaria faction to Exalted through quests or reputation items.",
        acquisition = "Difficulty: Medium - Build a specific Pandaria faction to Exalted through quests or reputation items.\n\n1. Start at Alliance shrine sage / Horde sage 62.8,23.4. Ask Sage Whiteheart (Alliance) or Sage Lotusbloom (Horde) which temple needs help today. Travel to the assigned Jade Serpent, Red Crane, White Tiger or Niuzao temple; the active hub rotates.\n\n2. Finish that temple's daily assignments and return for their hand-ins. Stolen Celestial Insignias from Zandalari rares supplement this reputation; Cloud Serpent reputation is a different bar.\n\n3. At Revered buy and USE the faction's Grand Commendation from your faction's shrine sage before earning the remaining reputation. The item unlocks increased future gains; merely carrying it does nothing.\n\n4. During Pandaria Timewalking, check Mistweaver Xia on Timeless Isle for this faction's commendations as an alternative. Use them on the character whose reputation you are raising. Continue to EXALTED and verify this achievement; buying a mount is unnecessary for the reputation criterion.",
        stepCount = 4,
        waypoints = {
            { mapID = 390, x = 0.846, y = 0.636, step = 1, label = "Alliance shrine sage / Horde sage 62.8,23.4" },
            { mapID = 554, x = 0.43, y = 0.552, step = 4, label = "Mistweaver Xia - Pandaria Timewalking only" },
        },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6543",
        sourceURL = "https://www.wowhead.com/achievement=6543#comments",
        reviewedAt = "2026-11-13",
