    [6548] = {
        achievementId = 6548,
        name = "The Lorewalkers",
        source = "The Lorewalkers",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Read fixed lore collections and deliver their mailed stories.",
        acquisition = "Difficulty: Easy - Read fixed lore collections and deliver their mailed stories.\n\n1. Visit Lorewalker Cho at the Seat of Knowledge above Mogu'shan Palace. Complete Your Private Collection if offered, then follow the nine mainland lore-collection achievement guides. Their numbered map pins identify the actual scrolls and cave entrances.\n\n2. Complete Between a Saurok and a Hard Place, Fish Tales, Heart of the Mantid Swarm, Hozen in the Mist, Ballad of Liu Lang, The Dark Heart of the Mogu, The Seven Burdens of Shaohao, The Song of the Yaungol and What Is Worth Fighting For by reading their objects.\n\n3. Check your mailbox for each completed collection's story scroll, use it to start its quest, then deliver it to Cho and let his story finish. Reading objects and handing in the letters both contribute; simply owning an account-wide lore achievement does not mean this character turned in its letter.\n\n4. At Revered buy and use Tan Shin Tiao's Grand Commendation before further gains. Complete missing story deliveries until Exalted. The dynamic quest list tracks these independent letters and their completed turn-ins; Archaeology artifact solves are a different activity.",
        stepCount = 4,
        waypoints = {
            {
                mapID = 390,
                x = 0.8320000000000001,
                y = 0.29600000000000004,
                step = 1,
                label = "Lorewalker Cho - introduction and story scrolls",
            },
            { mapID = 390, x = 0.8220000000000001, y = 0.294, step = 4, label = "Tan Shin Tiao - Grand Commendation" },
        },
        sources = { "https://www.wowhead.com/achievement=6548#comments:id=6367753" },
        wowheadUrl = "https://www.wowhead.com/achievement=6548",
        sourceURL = "https://www.wowhead.com/achievement=6548#comments",
        reviewedAt = "2026-11-13",
    },
    [6550] = {
        achievementId = 6550,
        name = "Order of the Cloud Serpent",
        source = "Order of the Cloud Serpent",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Build a specific Pandaria faction to Exalted through quests or reputation items.",
        acquisition = "Difficulty: Medium - Build a specific Pandaria faction to Exalted through quests or reputation items.\n\n1. Start at Elder Anli - Wild Things. Start Wild Things, meet Instructor Tong on Windward Isle and complete Beating the Odds, Empty Nests and Egg Collection. Choose an egg, deliver it to Skythorn and finish It's A... to unlock hatchling care.\n\n2. Complete Arboretum/hatchling dailies or repeatedly search Windward Isle's rock pillars for Onyx Eggs and deliver them to Anli through Onyx To Goodness. Continue the growing-serpent/flight lessons when offered; the old separate Cloud Serpent Riding skill is no longer required.\n\n3. At Revered buy and USE the faction's Grand Commendation from San Redscale at 56.6,44.4 before earning the remaining reputation. The item unlocks increased future gains; merely carrying it does nothing.\n\n4. During Pandaria Timewalking, check Mistweaver Xia on Timeless Isle for this faction's commendations as an alternative. Use them on the character whose reputation you are raising. Continue to EXALTED and verify this achievement; buying a mount is unnecessary for the reputation criterion.",
        stepCount = 4,
        waypoints = {
