    [6616] = {
        achievementId = 6616,
        name = "Pandaria Tamer",
        source = "Pandaria Tamer",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Capture one wild pet in every listed zone.",
        acquisition = "Difficulty: Medium - Capture one wild pet in every listed zone.\n\n1. Prepare a capture team, unlock Trap and track this achievement. Visit the original continent named here; Outland Nagrand and Shadowmoon Valley are different zones from their Draenor counterparts.\n\n2. Capture one paw-marked wild pet in EACH of these zones: Jade Forest, Valley of the Four Winds, Krasarang Wilds, Kun-Lai Summit, Townlong Steppes, Dread Wastes and Vale of Eternal Blossoms. Reduce its health below 35%, trap it and finish the battle successfully. Any capturable species and quality can satisfy that zone.\n\n3. Check the zone criterion before traveling onward. A purchased cage and merely winning without a capture do not replace a zone capture. If an invasion or destroyed phase has no suitable spawns, use that zone's Zidormi option to access its earlier Retail phase.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 424 },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6616",
        sourceURL = "https://www.wowhead.com/achievement=6616#comments",
        reviewedAt = "2026-11-13",
    },
    [6671] = {
        achievementId = 6671,
        name = "Seeds of Doubt",
        source = "Seeds of Doubt",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Collect the four corner crystals during the shadow phase.",
        acquisition = "Difficulty: Easy - Collect the four corner crystals during the shadow phase.\n\n1. Enter Temple of the Jade Serpent on Heroic and reach Sha of Doubt. Remove passive damage and dismiss pets. Body-pull or taunt without attacking; you need him alive for Bounds of Reality.\n\n2. When your shadow separates, leave it alive and click the crystals in all four corners of the room. Collect them quickly and verify four Seeds of Doubt stacks on your character. If the phase ends early, wait for the next separation and finish the circuit.\n\n3. With all four stacks still active, kill your shadow to end the shield phase and immediately kill Sha of Doubt. Do not kill him before the crystals appear or assume collecting only one crystal is enough.",
        stepCount = 3,
        waypoints = { { mapID = 371, x = 0.56, y = 0.58, step = 1, label = "Heroic Temple of the Jade Serpent - Sha of Doubt" } },
        sources = {
            "https://www.wowhead.com/achievement=6671#comments:id=5248144",
            "https://www.wowhead.com/achievement=6671#comments:id=1972163",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=6671",
        sourceURL = "https://www.wowhead.com/achievement=6671#comments",
        reviewedAt = "2026-11-13",
    },
    [6674] = {
        achievementId = 6674,
        name = "Anything You Can Do, I Can Do Better...",
        source = "Anything You Can Do, I Can Do Better...",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Needs a tank-specialized player, a second target and tightly controlled copied damage.",
        acquisition = "Difficulty: Hard - Needs a tank-specialized player, a second target and tightly controlled copied damage.\n\n1. Select Normal or Heroic raid difficulty outside Mogu'shan Vaults and enter at the mapped entrance. Use the original raid rather than Raid Finder for this encounter challenge. Remove uncontrolled cleave, damage shields and attacking pets whenever the following steps require preserving a boss or adds.\n\n2. Bring two characters, one in an actual tank SPECIALIZATION and the other preferably damage. Use 25-player Normal for a predictable fist, spear, staff sequence. The June 2026 successful report used level-41 characters to avoid lethal copied damage; at high level a single reflected Epicenter may kill Feng before the other copies.\n\n3. Body-pull Feng. The tank picks up the DARK Shroud of Reversal crystal. Target the second player while they are actually hit by an eligible ability, use the shroud to copy it, then target Feng and cast the copied ability back. Picking up the crystal or merely receiving the copy is insufficient.\n\n4. In the fist phase copy and CAST Lightning Fists and Epicenter. The second player must be struck by the traveling Lightning Fists stun, so face away or sit if high dodge prevents it. Cancel copied Epicenter immediately after starting it if its damage threatens to kill Feng.\n\n5. Lower Feng carefully into the spear phase and copy/cast Wildfire Spark from the second player's fire debuff. Then lower him into the staff phase and copy/cast Arcane Velocity and Arcane Resonance; Resonance is visible as the arcane circle/debuff and may not have a conventional boss cast bar.\n\n6. After all five different copies were actually cast, defeat Feng. The in-game tracker has failed to display intermediate copies in recent reports, so keep your own five-name checklist. A bear form without Guardian specialization cannot pick up the tank crystal; one ordinary solo character has no second player to target.",
        stepCount = 6,
        waypoints = { { mapID = 379, x = 0.596, y = 0.392, step = 1, label = "Mogu'shan Vaults entrance" } },
        sources = {
            "https://www.wowhead.com/achievement=6674#comments:id=2147117",
            "https://www.wowhead.com/achievement=6674#comments:id=1732939",
            "https://www.wowhead.com/achievement=6674#comments:id=5239323",
            "https://www.wowhead.com/achievement=6674#comments:id=6371052",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=6674",
        sourceURL = "https://www.wowhead.com/achievement=6674#comments",
        reviewedAt = "2026-11-13",
    },
    [6683] = {
        achievementId = 6683,
        name = "Less Than Three",
        source = "Less Than Three",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Never crowd-control three members of Mel'jarak's swarm simultaneously.",
        acquisition = "Difficulty: Easy - Never crowd-control three members of Mel'jarak's swarm simultaneously.\n\n1. Select Normal or Heroic raid difficulty outside Heart of Fear and enter at the mapped entrance. Use the original raid rather than Raid Finder for this encounter challenge. Remove uncontrolled cleave, damage shields and attacking pets whenever the following steps require preserving a boss or adds.\n\n2. Do not use the encounter's crowd-control spears at all on a high-level clear. Kill Mel'jarak's supporting groups with damage, prioritizing Amber-Trappers before they can imprison a solo character.\n\n3. Defeat Mel'jarak with at most TWO adds controlled at any one time throughout the encounter. No crowd control is a valid and simple route. If using a leveling group, assign only two controls and account for class stuns/other control effects rather than having everyone independently trap a target.",
        stepCount = 3,
        waypoints = { { mapID = 422, x = 0.391, y = 0.35, step = 1, label = "Heart of Fear entrance" } },
        sources = {
            "https://www.wowhead.com/achievement=6683#comments:id=2315329",
