    [6686] = {
        achievementId = 6686,
        name = "Straight Six",
        source = "Straight Six",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Allow the focus phase, then destroy the six pillars quickly.",
        acquisition = "Difficulty: Easy - Allow the focus phase, then destroy the six pillars quickly.\n\n1. Select Normal or Heroic raid difficulty outside Mogu'shan Vaults and enter at the mapped entrance. Use the original raid rather than Raid Finder for this encounter challenge. Remove uncontrolled cleave, damage shields and attacking pets whenever the following steps require preserving a boss or adds.\n\n2. At Elegon, use controlled damage to trigger Draw Power, then STOP attacking. Let all six Energy Charges reach the platform edges; killing the charges delays the pillar phase you need.\n\n3. Leave the transparent central floor before it disappears. The charges activate six Empyreal Focus pillars around the outside ring. Run the ring with instant ranged attacks and destroy every focus, keeping the gap between consecutive kills under ten seconds; comments clarify that the timer refreshes between pillars.\n\n4. When the floor returns, defeat Elegon. If a gap was too slow, another focus phase during the same encounter gives another opportunity. Do not jump onto the missing central floor to shorten the route.",
        stepCount = 4,
        waypoints = { { mapID = 379, x = 0.596, y = 0.392, step = 1, label = "Mogu'shan Vaults entrance" } },
        sources = {
            "https://www.wowhead.com/achievement=6686#comments:id=2615739",
