    [6688] = {
        achievementId = 6688,
        name = "Where's My Air Support?",
        source = "Where's My Air Support?",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Kill the flying Amberwing before Vo'jak reaches the platform.",
        acquisition = "Difficulty: Easy - Kill the flying Amberwing before Vo'jak reaches the platform.\n\n1. Enter Siege of Niuzao Temple on Heroic and begin Commander Vo'jak's defense event. Have a ranged attack ready and watch for the Sik'thik Amberwing approaching the platform.\n\n2. Target and kill the Amberwing during its low bombing pass while handling the waves below. It makes only a limited number of reachable passes; do not wait until Vo'jak has climbed the stairs and joined you.\n\n3. After confirming the Amberwing is dead, finish the remaining waves and kill Commander Vo'jak. Killing only the commander does not satisfy the prerequisite.",
