    [6689] = {
        achievementId = 6689,
        name = "Terrace of Endless Spring",
        source = "Terrace of Endless Spring",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Complete the listed legacy raid encounters.",
        acquisition = "Difficulty: Easy - Complete the listed legacy raid encounters.\n\n1. Enter Terrace of Endless Spring at the map pin. Normal is sufficient for this wing-completion achievement; choose Heroic or Mythic instead if combining it with the corresponding boss achievements.\n\n2. Kill every boss on this wing's checklist: Protectors of the Endless; Tsulong; Lei Shi; Sha of Fear. Defeat the three Protectors, Tsulong, Lei Shi and Sha of Fear in that order. The entrance is in The Veiled Stair, not at the Vale's Mogu'shan Palace.\n\n3. At Tsulong, damage his hostile night form or heal his friendly day form. For Lei Shi, use area damage to reveal Hide and kill animated protectors during Get Away/protection phases. If Heroic credit fails, check the actual instance difficulty; comments report success after switching between 10- and 25-player Heroic on a fresh weekly lockout and allowing bosses to engage before killing them.\n\n4. Open the achievement and check each named boss. A full clear from the entrance covers the wing; using a final-boss skip leaves skipped criteria unfinished.",
        stepCount = 4,
        waypoints = { { mapID = 433, x = 0.486, y = 0.616, step = 1, label = "Terrace of Endless Spring entrance" } },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6689",
        sourceURL = "https://www.wowhead.com/achievement=6689#comments",
        reviewedAt = "2026-11-13",
    },
    [6713] = {
        achievementId = 6713,
        name = "Quarrelsome Quilen Quintet",
        source = "Quarrelsome Quilen Quintet",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Find five small quilen, including a ledge jump and a hidden statue.",
        acquisition = "Difficulty: Medium - Find five small quilen, including a ledge jump and a hidden statue.\n\n1. Enter Mogu'shan Palace on Heroic. Collect all five Jade Quilen before finishing Xin, since later comments report a closed return door. Enable friendly nameplates, use /targetexact Jade Quilen and bind Interact With Target.\n\n2. Collect the first behind the two fighting quilen at the far side of the entrance hall. After Trial of the King, search beneath and around the fighting mogu for the second; its precise position can vary.\n\n3. Descend toward Gekkan. In the first flat antechamber, target the quilen on the right-hand ledge, jump onto the brazier, then jump toward it while pressing Interact With Target. A taller transformation can help a short character reach it.\n\n4. Before dropping to Gekkan, search the open vault halfway around the right-hand balcony for the fourth. An Ancient Mogu Key is not required for the already-open vault.\n\n5. Before Xin, clear the guards in the scrying-orb side rooms. Click an orb and wait for its large statue to break, then collect the small quilen revealed. Check the opposite room if the first statue has none.",
        stepCount = 5,
        waypoints = {
            { mapID = 390, x = 0.802, y = 0.331, step = 1, label = "Mogu'shan Palace - Heroic entrance" },
