    [6716] = {
        achievementId = 6716,
        name = "Between a Saurok and a Hard Place",
        source = "Between a Saurok and a Hard Place",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Read a fixed collection of lore objects; no random drop is required.",
        acquisition = "Difficulty: Easy - Read a fixed collection of lore objects; no random drop is required.\n\n1. Track the named lore objects and RIGHT-CLICK/read each monument or scroll. Flying past, killing nearby enemies or completing ordinary zone quests does not replace reading it. The map dropdown separates the guide's different zones.\n\n2. Read The Saurok near 67.7,29.5. Read the scroll near the eastern saurok coast.\n\n3. Read The Defiant near 55,16. Enter Ancient Passage north of Tavern in the Mists; take the second right tunnel, then left into the round Dark Rookery room. The scroll is near a headless statue, not on the mountain surface.\n\n4. Read The Last Stand near 32.8,29.4. Enter Riverblade Den BEHIND the waterfall from Krasarang; look on the projecting rock inside, not in the water above.\n\n5. Read The Deserters near 67.47,60.83. Read the scroll at the saurok site.\n\n6. Check every object criterion. The exploration achievement completes on reading the final missing object; the mailed story-scroll turn-in to Lorewalker Cho is a separate Lorewalkers reputation reward. For Vale objects, choose Zidormi's earlier Pandaria phase if the assault hides them.",
        stepCount = 6,
        waypoints = {
            { mapID = 371, x = 0.677, y = 0.295, step = 2, label = "The Saurok" },
            { mapID = 433, x = 0.55, y = 0.16, step = 3, label = "The Defiant" },
            { mapID = 418, x = 0.32799999999999996, y = 0.294, step = 4, label = "The Last Stand" },
            { mapID = 422, x = 0.6747, y = 0.6083, step = 5, label = "The Deserters" },
        },
        sources = { "https://www.wowhead.com/achievement=6716#comments:id=1721050" },
