    [6717] = {
        achievementId = 6717,
        name = "Power Overwhelming",
        source = "Power Overwhelming",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Three clears are needed, leaving a different protector last each time.",
        acquisition = "Difficulty: Easy - Three clears are needed, leaving a different protector last each time.\n\n1. Select Normal or Heroic raid difficulty outside Terrace of Endless Spring and enter at the mapped entrance. Use the original raid rather than Raid Finder for this encounter challenge. Remove uncontrolled cleave, damage shields and attacking pets whenever the following steps require preserving a boss or adds.\n\n2. Track the three protector names: Protector Kaolan, Elder Regail and Elder Asani. Choose one unfinished name to leave alive and kill the other two first with single-target attacks.\n\n3. Kill that chosen protector LAST and verify its criterion. Do not cleave all three down together, since that can give an unintended final death order.\n\n4. Repeat on fresh weekly clears until all three different last-survivor choices are ticked. The conservative route uses the same character across those clears, since comments report character-specific partial tracking. Killing Kaolan last is the old Elite loot variation, not a separate difficulty menu.",
        stepCount = 4,
        waypoints = { { mapID = 433, x = 0.486, y = 0.616, step = 1, label = "Terrace of Endless Spring entrance" } },
        sources = {
            "https://www.wowhead.com/achievement=6717#comments:id=2535613",
            "https://www.wowhead.com/achievement=6717#comments:id=1800368",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=6717",
        sourceURL = "https://www.wowhead.com/achievement=6717#comments",
        reviewedAt = "2026-11-13",
    },
    [6718] = {
        achievementId = 6718,
        name = "The Dread Approach",
        source = "The Dread Approach",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Complete the listed legacy raid encounters.",
        acquisition = "Difficulty: Easy - Complete the listed legacy raid encounters.\n\n1. Enter Heart of Fear at the map pin. Normal is sufficient for this wing-completion achievement; choose Heroic or Mythic instead if combining it with the corresponding boss achievements.\n\n2. Kill every boss on this wing's checklist: Imperial Vizier Zor'lok; Blade Lord Ta'yak; Garalon. Clear Zor'lok, Ta'yak, Garalon, Mel'jarak, Un'sok and Grand Empress Shek'zeer in order.\n\n3. Kill the trash guarding each boss to open the route. If Ta'yak reaches his tornado phase, follow the safe gaps along the corridor. Kill Un'sok before a solo-player construct transformation if possible; being the only player transformed can reset the fight.\n\n4. Open the achievement and check each named boss. A full clear from the entrance covers the wing; using a final-boss skip leaves skipped criteria unfinished.",
        stepCount = 4,
        waypoints = { { mapID = 422, x = 0.391, y = 0.35, step = 1, label = "Heart of Fear entrance" } },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6718",
        sourceURL = "https://www.wowhead.com/achievement=6718#comments",
        reviewedAt = "2026-11-13",
    },
    [6719] = {
        achievementId = 6719,
        name = "Heroic: Stone Guard",
        source = "Heroic: Stone Guard",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "A legacy boss kill; the selected raid difficulty must match.",
        acquisition = "Difficulty: Easy - A legacy boss kill; the selected raid difficulty must match.\n\n1. Outside the instance, right-click your character portrait and select Heroic raid difficulty. For the older raids also choose the legacy 10- or 25-player size. Enter Mogu'shan Vaults through the mapped entrance. Use a current high-level character rather than a Chromie Time leveling character.\n\n2. Follow Stone Guard, Feng, Gara'jal, the Four Kings, Elegon and Will of the Emperor in order. Your target is Stone Guard. Kill preceding bosses needed to reach it; clearing a different wing in Raid Finder does not award this difficulty-specific achievement.\n\n3. For Will of the Emperor on Heroic, destroy the four exposed pipes at the bottoms of the stairs to start the encounter; the broken central console is not the Heroic trigger. Kill both constructs. At Elegon, leave the transparent floor before it disappears if you cannot finish him immediately.\n\n4. Confirm the named kill appears in the achievement criteria. Boss loot and repeat attempts are constrained by the raid's weekly lockout; do not expect resetting the instance to resurrect a boss already saved dead.",
        stepCount = 4,
        waypoints = { { mapID = 379, x = 0.596, y = 0.392, step = 1, label = "Mogu'shan Vaults - Heroic entrance" } },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6719",
        sourceURL = "https://www.wowhead.com/achievement=6719#comments",
        reviewedAt = "2026-11-13",
    },
