    [6739] = {
        achievementId = 6739,
        name = "Silvershard Mines Victory",
        source = "Silvershard Mines Victory",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Team battleground results and queue availability determine progress.",
        acquisition = "Difficulty: Medium - Team battleground results and queue availability determine progress.\n\n1. Open Group Finder > Player vs. Player and select Silvershard Mines from the available battleground queues. Enter through the queue; visiting its outdoor gate does not start a match. The map view shows the battlefield for planning rather than an invented physical quest pickup.\n\n2. Stay inside friendly mine-cart circles to outnumber the enemy and escort carts into depots. Split the team to cover multiple tracks; fighting away from carts contributes little. Current Training Grounds wins have been reported to count for the Silvershard veteran counter.\n\n3. Finish 1 winning match. Stay until the match result registers and check the achievement counter. Losses and merely entering the map do not count; the hundred-win totals accumulate across matches.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 423 },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6739",
        sourceURL = "https://www.wowhead.com/achievement=6739#comments",
        reviewedAt = "2026-11-13",
    },
