    [6754] = {
        achievementId = 6754,
        name = "The Dark Heart of the Mogu",
        source = "The Dark Heart of the Mogu",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Read a fixed collection of lore objects; no random drop is required.",
        acquisition = "Difficulty: Easy - Read a fixed collection of lore objects; no random drop is required.\n\n1. Track the named lore objects and RIGHT-CLICK/read each monument or scroll. Flying past, killing nearby enemies or completing ordinary zone quests does not replace reading it. The map dropdown separates the guide's different zones.\n\n2. Read Spirit Binders near 42,17. Read the monument at the northern ruins.\n\n3. Read The Lost Dynasty near 51,31.7. Read the monument among the Krasari ruins.\n\n4. Read Valley of Emperors near 53,46. This pin is the TOMB ENTRANCE. Go inside to the lore object; old 58,71 directions refer to the interior map, not Kun-Lai's surface.\n\n5. Read The Thunder King near 40,77. Use the earlier Vale if required and read the monument.\n\n6. Check every object criterion. The exploration achievement completes on reading the final missing object; the mailed story-scroll turn-in to Lorewalker Cho is a separate Lorewalkers reputation reward. For Vale objects, choose Zidormi's earlier Pandaria phase if the assault hides them.",
        stepCount = 6,
        waypoints = {
            { mapID = 371, x = 0.42, y = 0.17, step = 2, label = "Spirit Binders" },
            { mapID = 418, x = 0.51, y = 0.317, step = 3, label = "The Lost Dynasty" },
            { mapID = 379, x = 0.53, y = 0.46, step = 4, label = "Valley of Emperors" },
            { mapID = 390, x = 0.4, y = 0.77, step = 5, label = "The Thunder King" },
        },
        sources = { "https://www.wowhead.com/achievement=6754#comments:id=1727979" },
        wowheadUrl = "https://www.wowhead.com/achievement=6754",
        sourceURL = "https://www.wowhead.com/achievement=6754#comments",
        reviewedAt = "2026-11-13",
