    [6821] = {
        achievementId = 6821,
        name = "School's Out Forever",
        source = "School's Out Forever",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Needs two participants to trigger enough Harsh Lessons.",
        acquisition = "Difficulty: Medium - Needs two participants to trigger enough Harsh Lessons.\n\n1. Bring another player to Darkmaster Gandling in Heroic Scholomance. Remove passive damage effects and pets. Engage him with a non-damaging taunt, interrupt or similar hostile ability, then stop attacking.\n\n2. Let Harsh Lesson repeatedly send the participants into side rooms. Keep Expired Test Subjects alive. When each gate opens, lead its ten subjects out toward the central staircase. If casts stall, switch who has aggro with taunts; one character alone does not trigger the needed room sequence.\n\n3. After at least five rooms have opened, check inside each for stragglers and gather at least fifty Expired Test Subjects together. Keep other enemies separate if you need to kill them. Older advice requiring five different players has been superseded by successful two-player runs.\n\n4. Kill all fifty subjects within twenty seconds using area damage away from Gandling. Confirm the achievement before finishing him. Counting nameplates is unreliable because only a limited number can be visible.",
        stepCount = 4,
        waypoints = { { mapID = 22, x = 0.69, y = 0.73, step = 1, label = "Heroic Scholomance - Gandling, bring another player" } },
        sources = {
            "https://www.wowhead.com/achievement=6821#comments:id=1860394",
            "https://www.wowhead.com/achievement=6821#comments:id=3250436",
            "https://www.wowhead.com/achievement=6821#comments:id=5147993",
