    [6830] = {
        achievementId = 6830,
        name = "Professional Zen Master",
        source = "Professional Zen Master",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Earn 75 Pandaria skill points in 1 distinct primary profession.",
        acquisition = "Difficulty: Medium - Earn 75 Pandaria skill points in 1 distinct primary profession.\n\n1. Learn the Pandaria tier of your chosen primary professions from their Pandaria trainers. Open the profession window and select its Pandaria skill bar; newer expansion skill points are separate.\n\n2. For gathering professions, gather Pandaria nodes or skin eligible Pandaria creatures. For crafting, train the tier's recipes and make orange/yellow recipes, replacing them as they become green or grey. Reach 75 earned Pandaria points and check that profession's criterion.\n\n3. Complete 1 distinct primary profession. Cooking, Fishing and Archaeology are secondary professions and do not satisfy this primary-profession requirement.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 371, 376, 379, 390 },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6830",
        sourceURL = "https://www.wowhead.com/achievement=6830#comments",
        reviewedAt = "2026-11-13",
    },
    [6835] = {
