    [6837] = {
        achievementId = 6837,
        name = "Zen Master Archaeologist",
        source = "Zen Master Archaeologist",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Raise the single Archaeology skill to 600.",
        acquisition = "Difficulty: Medium - Raise the single Archaeology skill to 600.\n\n1. Learn Archaeology from Harrison Jones in Stormwind or Belloc Brightblade in Orgrimmar. Enable dig sites on your world map, travel into a marked site and use Survey, following its distance color and direction until you uncover fragments.\n\n2. Survey and solve artifacts, returning to a trainer when you need a higher skill cap. Archaeology retains a combined skill bar, unlike expansion-split crafting professions.\n\n3. At 525 skill, Pandaria dig sites become available. Survey their Pandaren, Mogu and Mantid sites and solve projects until Archaeology reaches 600. Continue those racial projects for the collector and pristine-display achievements if desired.",
        stepCount = 3,
        waypoints = {
            { mapID = 84, x = 0.856, y = 0.258, step = 1, label = "Harrison Jones - Alliance Archaeology" },
            { mapID = 85, x = 0.49, y = 0.708, step = 1, label = "Belloc Brightblade - Horde Archaeology" },
        },
        areaMaps = { 371, 376, 418, 379, 388, 422, 390 },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6837",
        sourceURL = "https://www.wowhead.com/achievement=6837#comments",
        reviewedAt = "2026-11-13",
    },
    [6839] = {
        achievementId = 6839,
        name = "Zen Master Fisherman",
        source = "Zen Master Fisherman",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Level the Pandaria Fishing tier to 75 through catches.",
        acquisition = "Difficulty: Easy - Level the Pandaria Fishing tier to 75 through catches.\n\n1. Learn Pandaria Fishing from a Pandaria fishing trainer, such as the Anglers at Anglers Wharf in Krasarang Wilds. Check the Pandaria skill bar in your Fishing window.\n\n2. Fish Pandaria open water or schools and loot each catch, continuing until the Pandaria Fishing bar reaches 75. Using another expansion's fishing waters levels a different tier.\n\n3. Combine the catches with Pandarian Angler or Nat Pagle's rare-fish quests if desired. Nat friendship and Anglers reputation are separate objectives; neither is required just to reach the Fishing skill target.",
        stepCount = 3,
        waypoints = { { mapID = 418, x = 0.684, y = 0.434, step = 1, label = "Anglers Wharf - Pandaria Fishing and fishing water" } },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6839",
        sourceURL = "https://www.wowhead.com/achievement=6839#comments",
        reviewedAt = "2026-11-13",
    },
    [6844] = {
        achievementId = 6844,
        name = "The Vault of Mysteries",
        source = "The Vault of Mysteries",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Complete the listed legacy raid encounters.",
        acquisition = "Difficulty: Easy - Complete the listed legacy raid encounters.\n\n1. Enter Mogu'shan Vaults at the map pin. Normal is sufficient for this wing-completion achievement; choose Heroic or Mythic instead if combining it with the corresponding boss achievements.\n\n2. Kill every boss on this wing's checklist: The Four Kings; Elegon; Will of the Emperor. Follow Stone Guard, Feng, Gara'jal, the Four Kings, Elegon and Will of the Emperor in order.\n\n3. For Will of the Emperor on Heroic, destroy the four exposed pipes at the bottoms of the stairs to start the encounter; the broken central console is not the Heroic trigger. Kill both constructs. At Elegon, leave the transparent floor before it disappears if you cannot finish him immediately.\n\n4. Open the achievement and check each named boss. A full clear from the entrance covers the wing; using a final-boss skip leaves skipped criteria unfinished.",
        stepCount = 4,
        waypoints = { { mapID = 379, x = 0.596, y = 0.392, step = 1, label = "Mogu'shan Vaults entrance" } },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6844",
        sourceURL = "https://www.wowhead.com/achievement=6844#comments",
        reviewedAt = "2026-11-13",
    },
    [6845] = {
        achievementId = 6845,
        name = "Nightmare of Shek'zeer",
        source = "Nightmare of Shek'zeer",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Complete the listed legacy raid encounters.",
        acquisition = "Difficulty: Easy - Complete the listed legacy raid encounters.\n\n1. Enter Heart of Fear at the map pin. Normal is sufficient for this wing-completion achievement; choose Heroic or Mythic instead if combining it with the corresponding boss achievements.\n\n2. Kill every boss on this wing's checklist: Wind Lord Mel'jarak; Amber-Shaper Un'sok; Grand Empress Shek'zeer. Clear Zor'lok, Ta'yak, Garalon, Mel'jarak, Un'sok and Grand Empress Shek'zeer in order.\n\n3. Kill the trash guarding each boss to open the route. If Ta'yak reaches his tornado phase, follow the safe gaps along the corridor. Kill Un'sok before a solo-player construct transformation if possible; being the only player transformed can reset the fight.\n\n4. Open the achievement and check each named boss. A full clear from the entrance covers the wing; using a final-boss skip leaves skipped criteria unfinished.",
        stepCount = 4,
        waypoints = { { mapID = 422, x = 0.391, y = 0.35, step = 1, label = "Heart of Fear entrance" } },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6845",
        sourceURL = "https://www.wowhead.com/achievement=6845#comments",
        reviewedAt = "2026-11-13",
    },
    [6846] = {
