    [6874] = {
        achievementId = 6874,
        name = "Scenaturday",
        source = "Scenaturday",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Legacy scenario objective: the seven original scenarios.",
        acquisition = "Difficulty: Medium - Legacy scenario objective: the seven original scenarios.\n\n1. At the Seat of Knowledge above Mogu'shan Palace, speak to Lorewalker Fu for NORMAL scenarios at Vale 83.2,30.6. Select the seven original scenarios from his stories and enter the legacy scenario. If the assault phase hides the storytellers, ask Zidormi at 81.2,29.6 for the earlier Vale. These storytellers allow solo entry; the old Dungeon Finder queue is unnecessary.\n\n2. Use a Alliance character and complete these seven NORMAL stories on a Saturday: A Brewing Storm, Greenstone Village, Unga Ingoo, Brewmoon Festival, Crypt of Forgotten Kings, Arena of Annihilation and your faction's Theramore's Fall.\n\n3. You can accumulate the seven criteria across multiple Saturdays; they do not all have to fit one sitting. Use the in-game calendar/server date and check that the first completion ticks before doing the rest, since old comments disagree about historical timezone handling.\n\n4. Finish each scenario's final stage, then return to Fu for the next story. Check the individual criteria and repeat only missing stories on another Saturday. Heroic stories from Shin do not replace the normal checklist.",
        stepCount = 4,
        waypoints = {
            { mapID = 390, x = 0.8320000000000001, y = 0.306, step = 1, label = "Lorewalker Fu - Normal scenarios" },
            { mapID = 390, x = 0.812, y = 0.29600000000000004, step = 1, label = "Zidormi - earlier Vale if needed" },
        },
        sources = {
            "https://www.wowhead.com/achievement=6874#comments:id=1777733",
            "https://www.wowhead.com/achievement=6874#comments:id=2590641",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=6874",
        sourceURL = "https://www.wowhead.com/achievement=6874#comments",
        reviewedAt = "2026-11-13",
    },
    [6882] = {
        achievementId = 6882,
        name = "Temple of Kotmogu Veteran",
        source = "Temple of Kotmogu Veteran",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Team battleground results and queue availability determine progress.",
        acquisition = "Difficulty: Hard - Team battleground results and queue availability determine progress.\n\n1. Open Group Finder > Player vs. Player and select Temple of Kotmogu from the available battleground queues. Enter through the queue; visiting its outdoor gate does not start a match. The map view shows the battlefield for planning rather than an invented physical quest pickup.\n\n2. Pick up available Orbs of Power, protect carriers in the central pit for stronger scoring and focus enemy carriers so your team can take their orbs. Replace fallen carriers promptly.\n\n3. Finish 100 winning matches. Stay until the match result registers and check the achievement counter. Losses and merely entering the map do not count; the hundred-win totals accumulate across matches.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 449 },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6882",
        sourceURL = "https://www.wowhead.com/achievement=6882#comments",
        reviewedAt = "2026-11-13",
    },
    [6883] = {
        achievementId = 6883,
        name = "Silvershard Mines Veteran",
        source = "Silvershard Mines Veteran",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Team battleground results and queue availability determine progress.",
        acquisition = "Difficulty: Hard - Team battleground results and queue availability determine progress.\n\n1. Open Group Finder > Player vs. Player and select Silvershard Mines from the available battleground queues. Enter through the queue; visiting its outdoor gate does not start a match. The map view shows the battlefield for planning rather than an invented physical quest pickup.\n\n2. Stay inside friendly mine-cart circles to outnumber the enemy and escort carts into depots. Split the team to cover multiple tracks; fighting away from carts contributes little. Current Training Grounds wins have been reported to count for the Silvershard veteran counter.\n\n3. Finish 100 winning matches. Stay until the match result registers and check the achievement counter. Losses and merely entering the map do not count; the hundred-win totals accumulate across matches.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 423 },
        sources = { "https://www.wowhead.com/achievement=6883#comments:id=6265991" },
        wowheadUrl = "https://www.wowhead.com/achievement=6883",
