    [6928] = {
        achievementId = 6928,
        name = "Burning Man",
        source = "Burning Man",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Bring Korloff's fire attack to both groups of targetable dummies.",
        acquisition = "Difficulty: Easy - Bring Korloff's fire attack to both groups of targetable dummies.\n\n1. Enter current Scarlet Monastery on Heroic and clear trash near Brother Korloff. Find the two sets of THREE targetable training dummies beside the fountain pool, opposite the benches and along the covered walkways.\n\n2. Body-pull Korloff without damaging him. Stand beside the middle dummy of the first set and wait for Firestorm Kick to ignite all three. Move to the middle dummy in the opposite set and repeat.\n\n3. Track Burning Man and verify six dummies have been ignited. Then kill Korloff. Decorative dummies elsewhere are not substitutes, and killing him before he uses the needed fire attacks loses the attempt.",
        stepCount = 3,
        waypoints = { { mapID = 18, x = 0.82, y = 0.33, step = 1, label = "Heroic Scarlet Monastery - Korloff's courtyard" } },
        sources = {
            "https://www.wowhead.com/achievement=6928#comments:id=1691488",
            "https://www.wowhead.com/achievement=6928#comments:id=2066295",
            "https://www.wowhead.com/achievement=6928#comments:id=3121648",
