        sourceURL = "https://www.wowhead.com/achievement=6928#comments",
        reviewedAt = "2026-11-13",
    },
    [6929] = {
        achievementId = 6929,
        name = "And Stay Dead!",
        source = "And Stay Dead!",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Allow Mass Resurrection and kill all revived judicators before finishing Whitemane.",
        acquisition = "Difficulty: Easy - Allow Mass Resurrection and kill all revived judicators before finishing Whitemane.\n\n1. Enter current Scarlet Monastery on Heroic and reach the cathedral. Clear the room and locate the dead Scarlet Judicators in the left/east wing. Remove passive damage so Whitemane survives while you wait.\n\n2. Kill Commander Durand to bring out High Inquisitor Whitemane. Keep her alive and allow Mass Resurrection to finish. Her resurrection of Durand is a separate event; do not mistake it for the judicators' mass resurrection.\n\n3. Kill every revived Scarlet Judicator with single-target attacks while preserving Whitemane. Check the left wing for any remaining resurrected mobs, then defeat Whitemane and Durand if he is still alive. At high level, no initial damage to Whitemane is needed just to make her cast.",
        stepCount = 3,
        waypoints = { { mapID = 18, x = 0.82, y = 0.33, step = 1, label = "Heroic Scarlet Monastery - cathedral and east wing" } },
        sources = {
            "https://www.wowhead.com/achievement=6929#comments:id=1720937",
