    [6933] = {
        achievementId = 6933,
        name = "Who's Got Two Green Thumbs?",
        source = "Who's Got Two Green Thumbs?",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Keep the Enchanted Plant alive throughout Tsulong.",
        acquisition = "Difficulty: Easy - Keep the Enchanted Plant alive throughout Tsulong.\n\n1. Select Normal or Heroic raid difficulty outside Terrace of Endless Spring and enter at the mapped entrance. Use the original raid rather than Raid Finder for this encounter challenge. Remove uncontrolled cleave, damage shields and attacking pets whenever the following steps require preserving a boss or adds.\n\n2. Before engaging Tsulong, locate the friendly Enchanted Plant toward the northeast of his courtyard. If bringing a low-level group, assign a healer or hybrid to watch and heal it during the damaging night phase.\n\n3. Defeat Tsulong before the plant dies. A high-level fast kill usually makes this simple, but monitor the plant if deliberately waiting through day/night cycles. The condition is the plant's survival, not your own health or an arbitrary healing total.",
        stepCount = 3,
        waypoints = { { mapID = 433, x = 0.486, y = 0.616, step = 1, label = "Terrace of Endless Spring entrance" } },
        sources = { "https://www.wowhead.com/achievement=6933#comments:id=1762413" },
        wowheadUrl = "https://www.wowhead.com/achievement=6933",
        sourceURL = "https://www.wowhead.com/achievement=6933#comments",
        reviewedAt = "2026-11-13",
    },
    [6936] = {
        achievementId = 6936,
        name = "Candle in the Wind",
        source = "Candle in the Wind",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Light four end-room braziers during Ta'yak's wind phase.",
        acquisition = "Difficulty: Medium - Light four end-room braziers during Ta'yak's wind phase.\n\n1. Select Normal or Heroic raid difficulty outside Heart of Fear and enter at the mapped entrance. Use the original raid rather than Raid Finder for this encounter challenge. Remove uncontrolled cleave, damage shields and attacking pets whenever the following steps require preserving a boss or adds.\n\n2. Lower Ta'yak carefully to 20% while standing beside one of the four ALREADY-LIT central braziers. When the wind phase starts, those central fires become clickable and grant the thirty-second Flame Bearer buff.\n\n3. Take the flame and light both UNLIT braziers at one end of the room. One flame buff can light both; avoid tornadoes and use the side winds where helpful rather than spending the whole buff struggling down the central lane.\n\n4. Return to a central lit brazier for a fresh flame, cross to the other end and light its two unlit braziers. Only then kill Ta'yak, accounting for his side change around 10%. Check that all four end-room braziers are burning before the final hit.",
        stepCount = 4,
        waypoints = { { mapID = 422, x = 0.391, y = 0.35, step = 1, label = "Heart of Fear entrance" } },
        sources = {
            "https://www.wowhead.com/achievement=6936#comments:id=2551337",
