    [6937] = {
        achievementId = 6937,
        name = "Overzealous",
        source = "Overzealous",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Every player needs Zealous Parasite at Zor'lok's death.",
        acquisition = "Difficulty: Easy - Every player needs Zealous Parasite at Zor'lok's death.\n\n1. Select Normal or Heroic raid difficulty outside Heart of Fear and enter at the mapped entrance. Use the original raid rather than Raid Finder for this encounter challenge. Remove uncontrolled cleave, damage shields and attacking pets whenever the following steps require preserving a boss or adds.\n\n2. Start Zor'lok with a non-damaging hostile ability and preserve him. Small bugs near the room's columns become available after the encounter begins.\n\n3. Each player picks up a bug to gain Zealous Parasite. Check your debuff, then kill Zor'lok while EVERY player still has it. Dismiss pets and avoid a damage spell that would kill him before the bug pickup; uncontrolled demon imps can also end the fight prematurely.",
        stepCount = 3,
        waypoints = { { mapID = 422, x = 0.391, y = 0.35, step = 1, label = "Heart of Fear entrance" } },
