    [6945] = {
        achievementId = 6945,
        name = "Mantid Swarm",
        source = "Mantid Swarm",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Let Raigonn summon reinforcements, then kill only the boss.",
        acquisition = "Difficulty: Easy - Let Raigonn summon reinforcements, then kill only the boss.\n\n1. Reach Raigonn in Heroic Gate of the Setting Sun. Remove cleaving attacks, damage procs, retaliatory effects and pets so the reinforcements remain alive.\n\n2. Wait for at least one reinforcement wave to spawn before breaking his weak spot. An immediate kill before any adds appear has failed to grant credit in the comments.\n\n3. Use Artillery to reach the weak spot if needed, break it and finish Raigonn with single-target damage. Do not kill any Mantid reinforcements during either phase. This achievement is separate from the Glory of the Pandaria Hero requirements.",
        stepCount = 3,
        waypoints = { { mapID = 390, x = 0.158, y = 0.743, step = 1, label = "Heroic Gate of the Setting Sun - Raigonn" } },
