    [6946] = {
        achievementId = 6946,
        name = "Empowered Spiritualist",
        source = "Empowered Spiritualist",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Let Thalnos create the empowered zombies before killing him.",
        acquisition = "Difficulty: Easy - Let Thalnos create the empowered zombies before killing him.\n\n1. Enter current Scarlet Monastery on Heroic. At Thalnos the Soulrender, remove damage procs and pets, then body-pull without attacking.\n\n2. Allow Summon Empowered Spirit to complete and the spirits to possess nearby crusader corpses. Preserve the resulting Empowered Zombies. Wait for at least three casts as well as at least three living empowered zombies; a recent reply reports that two casts producing four zombies was insufficient.\n\n3. Kill only Thalnos with a single-target attack while the empowered zombies remain alive. Heroic is required; old Normal-mode reports predate changes. The achievement is not a Glory of the Pandaria Hero requirement.",
        stepCount = 3,
        waypoints = { { mapID = 18, x = 0.82, y = 0.33, step = 1, label = "Heroic Scarlet Monastery - Thalnos" } },
