    [6947] = {
        achievementId = 6947,
        name = "Four Square",
        source = "Four Square",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Personally hold every different orb color in one match.",
        acquisition = "Difficulty: Medium - Personally hold every different orb color in one match.\n\n1. Open Group Finder > Player vs. Player and select Temple of Kotmogu from the available battleground queues. Enter through the queue; visiting its outdoor gate does not start a match. The map view shows the battlefield for planning rather than an invented physical quest pickup.\n\n2. Track Cyan, Purple, Green and Orange. Pick up an available orb, help your team score with it and remember its color. You only hold one at a time; this is not your team's simultaneous four-orb control condition.\n\n3. After losing an orb normally, respawn and seek a DIFFERENT uncredited color as its carrier falls. Plan rotations with teammates while continuing to defend and score. All four personal color pickups must occur before this match ends; the next match starts a new attempt.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 449 },
        sources = { "https://www.wowhead.com/achievement=6947#comments:id=1837365" },
        wowheadUrl = "https://www.wowhead.com/achievement=6947",
        sourceURL = "https://www.wowhead.com/achievement=6947#comments",
        reviewedAt = "2026-11-13",
    },
    [6950] = {
        achievementId = 6950,
        name = "Powerball",
        source = "Powerball",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Survive with an orb in the central scoring area for ninety seconds.",
        acquisition = "Difficulty: Hard - Survive with an orb in the central scoring area for ninety seconds.\n\n1. Open Group Finder > Player vs. Player and select Temple of Kotmogu from the available battleground queues. Enter through the queue; visiting its outdoor gate does not start a match. The map view shows the battlefield for planning rather than an invented physical quest pickup.\n\n2. Collect an Orb of Power and enter the central pit. Ask healers and nearby teammates to protect you, save defensive abilities and use the pit's pillars/stairs to limit incoming attacks without leaving its scoring area.\n\n3. Hold the orb in the center for ninety seconds of active match time. The increasing carrier damage debuff makes survival harder, so coordinate rather than retreating outside the center. Do not rely on obsolete advice about waiting behind the final scoreboard after the battleground ends.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 449 },
        sources = { "https://www.wowhead.com/achievement=6950#comments:id=1788400" },
        wowheadUrl = "https://www.wowhead.com/achievement=6950",
