    [6970] = {
        achievementId = 6970,
        name = "Blackout",
        source = "Blackout",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Defeat one hundred enemy orb carriers across matches.",
        acquisition = "Difficulty: Medium - Defeat one hundred enemy orb carriers across matches.\n\n1. Open Group Finder > Player vs. Player and select Temple of Kotmogu from the available battleground queues. Enter through the queue; visiting its outdoor gate does not start a match. The map view shows the battlefield for planning rather than an invented physical quest pickup.\n\n2. Identify enemy players with the visible Orb of Power effect. Focus them with your team while their increasing damage-taken debuff makes them vulnerable; unrelated players without an orb are not the required targets.\n\n3. Participate in killing one hundred carriers and check the counter between matches. Work on this while helping your own carriers score. These are cumulative carrier kills, not one hundred ordinary battleground kills in a single match.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 449 },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6970",
        sourceURL = "https://www.wowhead.com/achievement=6970#comments",
