    },
    [6971] = {
        achievementId = 6971,
        name = "I've Got the Power",
        source = "I've Got the Power",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Your team must hold all four orbs when it wins.",
        acquisition = "Difficulty: Medium - Your team must hold all four orbs when it wins.\n\n1. Open Group Finder > Player vs. Player and select Temple of Kotmogu from the available battleground queues. Enter through the queue; visiting its outdoor gate does not start a match. The map view shows the battlefield for planning rather than an invented physical quest pickup.\n\n2. As your team approaches the winning score, identify any orb held by the opposition. Defeat that carrier and immediately pick up the freed orb instead of leaving it on its pedestal.\n\n3. Protect all FOUR friendly carriers until the match ends in victory. The team must control every orb at the final result; holding four earlier and losing one before the finish is insufficient. One character cannot personally carry all four.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 449 },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=6971",
        sourceURL = "https://www.wowhead.com/achievement=6971#comments",
