    [6974] = {
        achievementId = 6974,
        name = "Pandaria Explorer",
        source = "Pandaria Explorer",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Complete the seven mainland zone-exploration checklists.",
        acquisition = "Difficulty: Easy - Complete the seven mainland zone-exploration checklists.\n\n1. Track Explore Jade Forest, Valley of the Four Winds, Krasarang Wilds, Kun-Lai Summit, Townlong Steppes, Dread Wastes and Vale of Eternal Blossoms. Isle of Thunder, Isle of Giants and Timeless Isle are not additional criteria for this original meta.\n\n2. Use each zone's individual numbered exploration route and map pins. Land or fly low over an unrevealed named area until its tick appears. Choose the earlier Pandaria Vale through Zidormi if the assault phase interferes.\n\n3. Check that all seven exploration achievements are complete. Loremaster, lore-object reading and pet Safari captures are separate objectives even though they can be combined during the trip.",
        stepCount = 3,
