    [7039] = {
        achievementId = 7039,
        name = "The Long Riders",
        source = "The Long Riders",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Stay with one cart from its spawn through its capture without losing control.",
        acquisition = "Difficulty: Medium - Stay with one cart from its spawn through its capture without losing control.\n\n1. Open Group Finder > Player vs. Player and select Silvershard Mines from the available battleground queues. Enter through the queue; visiting its outdoor gate does not start a match. The map view shows the battlefield for planning rather than an invented physical quest pickup.\n\n2. Meet a new cart at the central spawn, enter its control circle immediately and escort it toward a depot. Keep enough friendly players inside to prevent the opposing team flipping control.\n\n3. Remain in its circle from spawn until the depot capture. Do not leave to fight elsewhere or let it turn neutral/enemy. Some recent Horde reports obtained credit while assigned to the Alliance team; if a clean Horde-side attempt fails to tick, check the currently available mixed-team/Training Grounds route rather than assuming a late takeover qualifies.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 423 },
        sources = { "https://www.wowhead.com/achievement=7039#comments:id=6045262" },
        wowheadUrl = "https://www.wowhead.com/achievement=7039",
