    [7230] = {
        achievementId = 7230,
        name = "Legend of the Brewfathers",
        source = "Legend of the Brewfathers",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Read a fixed collection of lore objects; no random drop is required.",
        acquisition = "Difficulty: Easy - Read a fixed collection of lore objects; no random drop is required.\n\n1. Track the named lore objects and RIGHT-CLICK/read each monument or scroll. Flying past, killing nearby enemies or completing ordinary zone quests does not replace reading it. The map dropdown separates the guide's different zones.\n\n2. Read Xin Wu Yin the Broken Hearted near 37.23,30.11. Read the Brewfather shrine.\n\n3. Read Quan Tou Kuo the Two Fisted near 81.46,11.52. Read the northeastern mountain shrine. Retail 9.1 restored Krasarang's original map; the shifted BFA 85.8,5.8 coordinates are obsolete.\n\n4. Read Ren Yun the Blind near 44.72,52.38. Read the mountain Brewfather shrine.\n\n5. Check every object criterion. The exploration achievement completes on reading the final missing object; the mailed story-scroll turn-in to Lorewalker Cho is a separate Lorewalkers reputation reward. For Vale objects, choose Zidormi's earlier Pandaria phase if the assault hides them.",
        stepCount = 5,
        waypoints = {
            { mapID = 371, x = 0.37229999999999996, y = 0.3011, step = 2, label = "Xin Wu Yin the Broken Hearted" },
