            { mapID = 379, x = 0.4472, y = 0.5238, step = 4, label = "Ren Yun the Blind" },
        },
        sources = { "https://www.wowhead.com/achievement=7230#comments:id=1726780" },
        wowheadUrl = "https://www.wowhead.com/achievement=7230",
        sourceURL = "https://www.wowhead.com/achievement=7230#comments",
