    [7292] = {
        achievementId = 7292,
        name = "Green Acres",
        source = "Green Acres",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Plant, tend and personally harvest Sunsong Ranch crops.",
        acquisition = "Difficulty: Easy - Plant, tend and personally harvest Sunsong Ranch crops.\n\n1. Start Farmer Yoon's A Helping Hand at Sunsong Ranch and complete the Learn and Grow lessons. Buy seeds from Merchant Greenfield, till available plots and plant one seed in each.\n\n2. Fix each crop's condition: water parched plants, spray infestations, pull weeds or remove vermin using the indicated interaction. Leave healthy plants to mature at the next daily growth reset, then personally click and harvest them.\n\n3. Harvest 1 crop and check the counter. The introductory harvest may complete the first-crop achievement; buying vegetables does not.",
        stepCount = 3,
        waypoints = {
            { mapID = 376, x = 0.52, y = 0.48100000000000004, step = 1, label = "Farmer Yoon - Sunsong Ranch" },
            { mapID = 376, x = 0.528, y = 0.52, step = 1, label = "Merchant Greenfield - seeds" },
