    [7295] = {
        achievementId = 7295,
        name = "Listen to the Drunk Fish",
        source = "Listen to the Drunk Fish",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Seven vegetables need their respective high-yield forecast harvests.",
        acquisition = "Difficulty: Medium - Seven vegetables need their respective high-yield forecast harvests.\n\n1. Ask Jogu the Drunk at Halfhill for TOMORROW's high-yield crop. His fee decreases with friendship and is free at Best Friend. Buy the predicted vegetable's seeds and plant them today.\n\n2. Tend them, wait through the next DAILY QUEST RESET, then harvest on the forecast day. Old comments warn that harvesting at midnight before the quest reset can mature the plant without awarding this forecast criterion.\n\n3. Repeat until Juicycrunch Carrot, Green Cabbage, Scallions, Mogu Pumpkin, Red Blossom Leek, Pink Turnip and White Turnip all tick. Witchberries, Striped Melons and Jade Squash are not criteria even when Jogu predicts them. Buying vegetables or harvesting a different day's planting does not substitute.",
        stepCount = 3,
        waypoints = {
            { mapID = 376, x = 0.536, y = 0.526, step = 1, label = "Jogu the Drunk - tomorrow's forecast" },
            { mapID = 376, x = 0.528, y = 0.52, step = 1, label = "Merchant Greenfield - vegetable seeds" },
            { mapID = 376, x = 0.52, y = 0.484, step = 2, label = "Sunsong Ranch - harvest after daily reset" },
        },
        sources = {
            "https://www.wowhead.com/achievement=7295#comments:id=1722956",
            "https://www.wowhead.com/achievement=7295#comments:id=1803123",
