        reviewedAt = "2026-11-13",
    },
    [7296] = {
        achievementId = 7296,
        name = "Ain't Lost No More",
        source = "Ain't Lost No More",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Unlock the farmer treasure story and return Thistle's legacy.",
        acquisition = "Difficulty: Medium - Unlock the farmer treasure story and return Thistle's legacy.\n\n1. Reach Exalted with The Tillers and Best Friend with all ten farmers, then kill the Enormous Cattail Grouper in Cattail Lake beside Fish Fellreed until the quest-starting Old Map of Thistle's Treasure (86404) drops.\n\n2. Use the map and follow the offered treasure quest with its friendly escort. Enter the cave around Valley 37,23 and STAY with the escort instead of racing ahead; leaving her behind can despawn the event.\n\n3. Loot the treasure chest, use its follow-up quest item to start The Heartland Legacy (31315), and return the legacy as directed. Finish the turn-in for the achievement. If the escort vanished, clear the path and return/relog at the entrance to let her reappear rather than assuming the chest alone finished the chain.",
        stepCount = 3,
        waypoints = {
            {
                mapID = 376,
                x = 0.41700000000000004,
                y = 0.3,
                step = 1,
                label = "Cattail Lake - Enormous Cattail Grouper / Fish Fellreed",
