    [7329] = {
        achievementId = 7329,
        name = "Pandaren Cuisine",
        source = "Pandaren Cuisine",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Eat each listed food; cooking it personally is unnecessary.",
        acquisition = "Difficulty: Easy - Eat each listed food; cooking it personally is unnecessary.\n\n1. Track the food checklist. Buy finished dishes from vendors/other players or cook them yourself at Halfhill. These are eating achievements, unlike The Pandaren Gourmet's personal cooking requirement.\n\n2. Obtain and EAT one of every missing dish: Sliced Peaches; Perfectly Cooked Instant Noodles; Toasted Fish Jerky; Dried Needle Mushrooms; Pounded Rice Cake; Yak Cheese Curds; Dried Peaches; Boiled Silkworm Pupa; Roasted Barley Tea; Blanched Needle Mushrooms; Red Bean Bun; Tangy Yogurt; Peach Pie; Skewered Peanut Chicken; Pearl Milk Tea; Green Curry Fish. Use the actual food, wait for its consumption tick and check its criterion before moving to the next; merely buying or cooking it is insufficient.\n\n3. Most basic dishes are sold by Pandaria inn/food vendors. Blanched Needle Mushrooms and Perfectly Cooked Instant Noodles need cooking or another player's prepared food; learn the starter recipes from Sungshin. Check the exact food names rather than substituting another mushroom or noodle item.",
        stepCount = 3,
        waypoints = { { mapID = 376, x = 0.536, y = 0.512, step = 1, label = "Sungshin Ironpaw - Halfhill recipes / ingredients" } },
        sources = { "https://www.wowhead.com/achievement=7329#comments:id=1714093" },
        wowheadUrl = "https://www.wowhead.com/achievement=7329",
        sourceURL = "https://www.wowhead.com/achievement=7329#comments",
        reviewedAt = "2026-11-13",
    },
    [7330] = {
        achievementId = 7330,
        name = "Pandaren Delicacies",
        source = "Pandaren Delicacies",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Eat each listed food; cooking it personally is unnecessary.",
        acquisition = "Difficulty: Easy - Eat each listed food; cooking it personally is unnecessary.\n\n1. Track the food checklist. Buy finished dishes from vendors/other players or cook them yourself at Halfhill. These are eating achievements, unlike The Pandaren Gourmet's personal cooking requirement.\n\n2. Obtain and EAT one of every missing dish: Rice Pudding; Sauteed Carrots; Ginseng Tea; Swirling Mist Soup; Shrimp Dumplings; Wildfowl Roast; Charbroiled Tiger Steak; Golden Carp Consomme; Fish Cake; Valley Stir Fry; Jade Witch Brew; Wildfowl Ginseng Soup; Braised Turtle; Fire Spirit Salmon; Twin Fish Platter; Eternal Blossom Fish; Sea Mist Rice Noodles; Spicy Vegetable Chips; Mad Brewer's Breakfast; Spicy Salmon; Mogu Fish Stew; Steamed Crab Surprise; Chun Tian Spring Rolls; Black Pepper Ribs and Shrimp. Use the actual food, wait for its consumption tick and check its criterion before moving to the next; merely buying or cooking it is insufficient.\n\n3. The twenty-four delicacies include all six Way recipe families. Buy difficult finished dishes rather than leveling every Way solely for this eating achievement. Consuming a banquet or another similar stat food does not replace a specifically named dish.",
        stepCount = 3,
        waypoints = { { mapID = 376, x = 0.536, y = 0.512, step = 1, label = "Sungshin Ironpaw - Halfhill recipes / ingredients" } },
        sources = { "https://www.wowhead.com/achievement=7330#comments:id=1714083" },
