    [7338] = {
        achievementId = 7338,
        name = "Collector: Pandaren Tea Sets",
        source = "Collector: Pandaren Tea Sets",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Random project selection; restore 5 copies of one Pandaren artifact.",
        acquisition = "Difficulty: Medium - Random project selection; restore 5 copies of one Pandaren artifact.\n\n1. Learn Archaeology and reach 525 skill to unlock Pandaria dig sites. You need 5 completed solves of Pandaren Tea Set, not 5 fragments or looted copies from another player.\n\n2. Open Archaeology and enable dig sites on the Pandaria continent map. Survey the current sites, clearing each completely so replacements appear. Use the Pandaren fragment projects; the neighboring Mogu branch cannot produce this artifact.\n\n3. Keep solving the Pandaren branch until Pandaren Tea Set is the active project. Its base cost is 50 Pandaren fragments. Use Pandaren Pottery Shard in its available keystone sockets to replace twenty fragments per socket.\n\n4. Solve and repeat until the tracker reaches 5. Project order is random, so there is no fixed number of total solves. Crate ordinary completed commons into Restored Artifacts after solving; keep newly found pristine quest items for their display hand-ins. Buying an ordinary artifact does not count as restoring it.",
        stepCount = 4,
        waypoints = {},
        areaMaps = { 371, 376, 418, 379, 388, 422, 390 },
        sources = { "https://www.wowhead.com/achievement=7338#comments" },
