    [7378] = {
        achievementId = 7378,
        name = "Jack of All Trades",
        source = "Jack of All Trades",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Earn 75 Pandaria skill points in 5 distinct primary professions.",
        acquisition = "Difficulty: Hard - Earn 75 Pandaria skill points in 5 distinct primary professions.\n\n1. Learn the Pandaria tier of your chosen primary professions from their Pandaria trainers. Open the profession window and select its Pandaria skill bar; newer expansion skill points are separate.\n\n2. For gathering professions, gather Pandaria nodes or skin eligible Pandaria creatures. For crafting, train the tier's recipes and make orange/yellow recipes, replacing them as they become green or grey. Reach 75 earned Pandaria points and check that profession's criterion.\n\n3. Complete 5 distinct primary professions. Use alts to preserve your existing professions. These breadth criteria share progress; Cooking, Fishing and Archaeology do not count among the eleven primary professions.",
        stepCount = 3,
        waypoints = {},
        areaMaps = { 371, 376, 379, 390 },
        sources = { "https://www.wowhead.com/achievement=7378#comments:id=1706088" },
