    [7381] = {
        achievementId = 7381,
        name = "Restore Balance",
        source = "Restore Balance",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Find and right-click one broken incense burner.",
        acquisition = "Difficulty: Easy - Find and right-click one broken incense burner.\n\n1. Travel to the Shrine of Fellowship on the mountain southwest of Tian Monastery. Without flying, start up the stairs at Jade Forest 31.9,33.6, turn right and follow the winding mountain path toward the small bridge.\n\n2. At 34.08,33.46, look for the Broken Incense Burner on the RIGHT immediately before the arched red-trimmed bridge. Right-click it to put its leaning piece upright; standing at the shrine alone does not count.\n\n3. The achievement completes immediately. The burner later leans over again for other players; that does not undo your credit, and there is no additional cinematic or quest chain to unlock.",
        stepCount = 3,
        waypoints = {
            { mapID = 371, x = 0.319, y = 0.336, step = 1, label = "Footpath stairs - turn right uphill" },
            { mapID = 371, x = 0.3408, y = 0.3346, step = 2, label = "Broken Incense Burner - right of bridge" },
        },
        sources = {
            "https://www.wowhead.com/achievement=7381#comments:id=1719526",
