    [7479] = {
        achievementId = 7479,
        name = "The Shado-Master",
        source = "The Shado-Master",
        sourceType = "Achievement",
        difficulty = "hard",
        difficultyReason = "Companion counters, three daily rotations and several avoidance challenges.",
        acquisition = "Difficulty: Hard - Companion counters, three daily rotations and several avoidance challenges.\n\n1. Reach Shado-Pan Exalted, unlock all nine companions for Proven Strength and complete fifteen credited dailies with EACH for Getting Around. Use dismounted hand-ins with the companion present; balance progress across the rotating groups.\n\n2. Complete each of Omnia, Wu Kao and Blackguard without a companion or leaving Townlong for Loner and a Rebel. In separate suitable attempts finish Silent Assassin, Know Your Role and Fire in the Yaung-hole using their detailed guides.\n\n3. Finish the Exalted Surprise Attack finale for Defender of Gods, kill the outdoor Sha of Anger for Settle Down Bro, and clear Heroic Shado-Pan Monastery. The retired Challenge Mode Gold was replaced by the Heroic dungeon criterion.\n\n4. Check all ten current meta criteria for the Shado-Master title. A missing daily rotation or companion counter is not repaired by another ordinary monastery clear.",
        stepCount = 4,
        waypoints = {
            { mapID = 388, x = 0.49, y = 0.705, step = 1, label = "Shado-Pan Garrison - companions and daily challenges" },
            { mapID = 379, x = 0.535, y = 0.653, step = 3, label = "Sha of Anger" },
            { mapID = 379, x = 0.36700000000000005, y = 0.474, step = 3, label = "Heroic Shado-Pan Monastery" },
        },
        sources = {
            "https://www.wowhead.com/achievement=7479#comments:id=1998361",
            "https://www.wowhead.com/achievement=7479#comments:id=6029740",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=7479",
        sourceURL = "https://www.wowhead.com/achievement=7479#comments",
        reviewedAt = "2026-11-13",
    },
    [7502] = {
        achievementId = 7502,
        name = "Savior of Stoneplow",
        source = "Savior of Stoneplow",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Finish the Valley/Krasarang student stories, then a scripted defense.",
        acquisition = "Difficulty: Medium - Finish the Valley/Krasarang student stories, then a scripted defense.\n\n1. Progress the Valley through the Hidden Master's Training and Discipline and the outdoor brewery story, then complete the relevant Krasarang student branches through Temple of the Red Crane and your faction's western camp. Nayeli Lagoon's raft/treasure branch is not mandatory for this defense.\n\n2. At the brewery, check Emmi for Stoneplow Thirsts, then deliver the keg. Also take Hope Springs Eternal from the Red Crane temple, or your faction's Warn Stoneplow alternative if that breadcrumb is offered instead.\n\n3. In Stoneplow finish ALL three parallel errands: The Swarm Begins, The Mantidote and It Does You No Good In The Keg. Some complete remotely; finish their turn-ins before looking for Students No More.\n\n4. Find the students on the small hill at 11.61,49.51 for Students No More. If they appear dead and no event begins, pull a mantid to them and kill it over their bodies. Complete the escort, then Retreat!.\n\n5. Take The Savior of Stoneplow from Master Bruised Paw. Speak to Miss Fanny the mushan for the launch into the Ik'thik Colossus and use the granted martial-arts controls to destroy it from inside. Finish the quest and collect the achievement.",
        stepCount = 5,
        waypoints = {
            { mapID = 376, x = 0.86, y = 0.222, step = 1, label = "Chen - Valley story start" },
            { mapID = 376, x = 0.36200000000000004, y = 0.684, step = 2, label = "Emmi - Stoneplow Thirsts" },
            {
                mapID = 418,
                x = 0.41600000000000004,
                y = 0.46299999999999997,
                step = 2,
                label = "Temple - Hope Springs Eternal",
            },
            { mapID = 376, x = 0.18100000000000002, y = 0.557, step = 3, label = "Stoneplow - three parallel errands" },
            { mapID = 376, x = 0.1161, y = 0.4951, step = 4, label = "Students No More - small hill" },
            { mapID = 376, x = 0.179, y = 0.557, step = 5, label = "Master Bruised Paw / Miss Fanny" },
        },
        sources = {
            "https://www.wowhead.com/achievement=7502#comments:id=1757890",
            "https://www.wowhead.com/achievement=7502#comments:id=3127659",
            "https://www.wowhead.com/achievement=7502#comments:id=5598369",
            "https://www.wowhead.com/achievement=7502#comments:id=1724121",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=7502",
        sourceURL = "https://www.wowhead.com/achievement=7502#comments",
