    [7509] = {
        achievementId = 7509,
        name = "Scenaturday",
        source = "Scenaturday",
        sourceType = "Achievement",
        difficulty = "medium",
        difficultyReason = "Legacy scenario objective: the seven original scenarios.",
        acquisition = "Difficulty: Medium - Legacy scenario objective: the seven original scenarios.\n\n1. At the Seat of Knowledge above Mogu'shan Palace, speak to Lorewalker Fu for NORMAL scenarios at Vale 83.2,30.6. Select the seven original scenarios from his stories and enter the legacy scenario. If the assault phase hides the storytellers, ask Zidormi at 81.2,29.6 for the earlier Vale. These storytellers allow solo entry; the old Dungeon Finder queue is unnecessary.\n\n2. Use a Horde character and complete these seven NORMAL stories on a Saturday: A Brewing Storm, Greenstone Village, Unga Ingoo, Brewmoon Festival, Crypt of Forgotten Kings, Arena of Annihilation and your faction's Theramore's Fall.\n\n3. You can accumulate the seven criteria across multiple Saturdays; they do not all have to fit one sitting. Use the in-game calendar/server date and check that the first completion ticks before doing the rest, since old comments disagree about historical timezone handling.\n\n4. Finish each scenario's final stage, then return to Fu for the next story. Check the individual criteria and repeat only missing stories on another Saturday. Heroic stories from Shin do not replace the normal checklist.",
        stepCount = 4,
        waypoints = {
            { mapID = 390, x = 0.8320000000000001, y = 0.306, step = 1, label = "Lorewalker Fu - Normal scenarios" },
            { mapID = 390, x = 0.812, y = 0.29600000000000004, step = 1, label = "Zidormi - earlier Vale if needed" },
        },
        sources = {
            "https://www.wowhead.com/achievement=6874#comments:id=1777733",
            "https://www.wowhead.com/achievement=6874#comments:id=2590641",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=7509",
        sourceURL = "https://www.wowhead.com/achievement=7509#comments",
        reviewedAt = "2026-11-13",
    },
    [7518] = {
        achievementId = 7518,
        name = "Wanderers, Dreamers, and You",
        source = "Wanderers, Dreamers, and You",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Attend a short scheduled weekly beach ceremony.",
        acquisition = "Difficulty: Easy - Attend a short scheduled weekly beach ceremony.\n\n1. Travel to Turtle Beach in Krasarang Wilds near Liu Lang's statue. The Wanderer's Festival occurs on Sunday evening for EU/US region schedules; be present BEFORE a ceremony starts or remain until its closing speech.\n\n2. EU comments report ceremonies around 21:00-21:23 and 23:00-23:23 server time. Regional daylight-saving handling and Oceanic servers differ, so use the in-game calendar/server clock rather than your computer clock. A 2024 Oceanic report places it on Monday afternoon locally.\n\n3. Stay for the actual OPENING or CLOSING announcement. Arriving two minutes after the start does not retroactively award opening credit, but remaining through the closing speech can complete it. The Wanderer's Festival Hatchling capture is optional and separate.",
        stepCount = 3,
        waypoints = { { mapID = 418, x = 0.722, y = 0.311, step = 1, label = "Turtle Beach - Wanderer's Festival ceremony" } },
        sources = {
            "https://www.wowhead.com/achievement=7518#comments:id=1786243",
            "https://www.wowhead.com/achievement=7518#comments:id=5940576",
            "https://www.wowhead.com/achievement=7518#comments:id=5872362",
            "https://www.wowhead.com/achievement=7518#comments:id=5814236",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=7518",
        sourceURL = "https://www.wowhead.com/achievement=7518#comments",
        reviewedAt = "2026-11-13",
    },
    [7522] = {
        achievementId = 7522,
        name = "Crypt of Forgotten Kings",
        source = "Crypt of Forgotten Kings",
        sourceType = "Achievement",
        difficulty = "easy",
        difficultyReason = "Legacy scenario objective: Crypt of Forgotten Kings.",
        acquisition = "Difficulty: Easy - Legacy scenario objective: Crypt of Forgotten Kings.\n\n1. At the Seat of Knowledge above Mogu'shan Palace, speak to Lorewalker Fu for NORMAL scenarios at Vale 83.2,30.6. Select Crypt of Forgotten Kings from his stories and enter the legacy scenario. If the assault phase hides the storytellers, ask Zidormi at 81.2,29.6 for the earlier Vale. These storytellers allow solo entry; the old Dungeon Finder queue is unnecessary.\n\n2. Descend through the crypt, fight the guardians and sha, avoid floor traps and continue to the final chamber. Defeat the Abomination of Anger while moving away from red ground clouds.\n\n3. Finish every stage until the scenario-complete banner appears and check the achievement. For another attempt, leave the instance and ask the storyteller for the same story again; raid weekly loot lockouts do not govern ordinary scenario completion.",
        stepCount = 3,
        waypoints = {
            { mapID = 390, x = 0.8320000000000001, y = 0.306, step = 1, label = "Lorewalker Fu - Normal scenarios" },
            { mapID = 390, x = 0.812, y = 0.29600000000000004, step = 1, label = "Zidormi - earlier Vale if needed" },
        },
        sources = {},
        wowheadUrl = "https://www.wowhead.com/achievement=7522",
        sourceURL = "https://www.wowhead.com/achievement=7522#comments",
        reviewedAt = "2026-11-13",
    },
    [7523] = {
