--[====[
Preserved inactive research: Data/Expansions/MistsOfPandaria/AchievementQuestRoutes.lua
This material is retained for reference and does not register character quest routes.

local _,TDP=...
local guides,routes=TDP.CollectionWalkthroughs.achievements,TDP.CollectionQuestRoutes
local helper=TDP.PandariaAchievementGuide
local quests=TDP.PandariaAchievementQuests
local function point(map,x,y) return {mapID=map,x=x/100,y=y/100} end
local function copy(v)
 if type(v)~="table" then return v end
 local r={} for k,x in pairs(v) do r[k]=copy(x) end return r
end
local function attach(id,route,keepPins)
 local g=guides[id]
 if not g then return end
 g.questRoutes=g.questRoutes or {}
 g.questRoutes[#g.questRoutes+1]=route
 if keepPins~=false then g.keepReferencePins=true end
end
local function define(key,name,list,options)
 local r=options or {}
 r.key,r.name,r.quests,r.version,r.reviewedAt=key,name,list,1,"2026-11-13"
 routes[key]=r
 return r
end
local function chain(key,name,ends,options)
 local list,seen,visiting={},{},{}
 local function visit(id)
  if seen[id] or visiting[id] then return end
  local q=quests[id]
  if not q then return end
  visiting[id]=true
  for _,pre in ipairs(q.requires or {}) do visit(pre) end
  visiting[id]=nil
  seen[id]=true
  list[#list+1]=copy(q)
 end
 for _,id in ipairs(ends) do visit(id) end
 local opts=options or {}
 if #ends==1 and not opts.endQuestID then opts.endQuestID=ends[1] end
 return define(key,name,list,opts)
end
local function clone(key,id,name,source,ending)
 local original=routes[source]
 if not original then return end
 local r=copy(original)
 r.key,r.name=key,name
 r.optional,r.factionID,r.standing,r.satisfiedPin,r.repeatableRewards=nil,nil,nil,nil,nil
 r.completionText="Prerequisite story completed - follow this achievement's remaining numbered steps."
 if ending then
  local last
  for i,q in ipairs(r.quests) do if q.questID==ending then last=i; break end end
  if last then while #r.quests>last do table.remove(r.quests) end end
  r.endQuestID,r.endQuestIDs=ending,nil
 end
 routes[key]=r
 attach(id,r)
 return r
end
