  local r=chain("mop-ach-"..id.."-"..c.endQuestID,c.name,{c.endQuestID},{
   faction=faction,compact=true,achievementID=id,criteriaID=c.criteriaID,
   rankFactionID=id==6540 and 1337 or nil,
