 for _,p in ipairs(rows) do
  list[#list+1]={questID=p[5],name=p[4],requires={},pickup=point(p[1],p[2],p[3]),pickupReference=true,
   instructions=p[6].." Interact and personally loot/claim this treasure. This character's completed finds are skipped automatically."}
 end
 attach(r[1],define("mop-ach-treasure-"..r[1],"Treasure candidates - find "..r[2].." distinct treasures",list,{requiredQuestCount=r[2],
  after="Candidates are alternatives. Stop once the achievement's required distinct-treasure total is reached; not every candidate is mandatory."}))
end
