local trainerLocations={}
local function trainerKey(name)
 return name:gsub("^Grand Master ",""):gsub("^Stone Cold ",""):lower()
end
for _,region in ipairs(helper.tamerRegions) do
 for _,t in ipairs(region[4]) do
  local faction=region[3]
  if t[4]:find("Trixxy") or t[4]:find("Lydia") then faction=nil end
  trainerLocations[trainerKey(t[4])]={mapID=t[1],x=t[2]/100,y=t[3]/100,faction=faction,counters=t[5]}
 end
end
for _,r in ipairs({{"Burning Pandaren Spirit",388,57,42.2},{"Flowing Pandaren Spirit",422,61.2,87.4},{"Whispering Pandaren Spirit",371,28.8,36},{"Thundering Pandaren Spirit",379,64.8,93.6}}) do
 trainerLocations[trainerKey(r[1])]={mapID=r[2],x=r[3]/100,y=r[4]/100}
end
local dailies={}
for _,r in ipairs(dailyRows) do
 local trainer=trainerLocations[trainerKey(r[2])]
 if trainer then
  dailies[#dailies+1]={questID=r[1],name=r[2],requires={},daily=true,activeOnly=true,faction=trainer.faction,
   pickup=point(trainer.mapID,trainer.x*100,trainer.y*100),turnIn=point(trainer.mapID,trainer.x*100,trainer.y*100),turnInReference=false,objectiveReference=true,
   instructions="Defeat "..r[2].." with the daily ACCEPTED, then turn it in. "..(trainer.counters and "Use the regional guide's "..trainer.counters.." counters and time avoidance for its big attacks." or "Use the four-spirit counters in the guide.") }
 elseif r[1]==32604 or r[1]==32868 or r[1]==32869 then
  dailies[#dailies+1]={questID=r[1],name=r[2],requires={},daily=true,activeOnly=true,
   pickupByFaction={Alliance=point(390,86.6,60.2),Horde=point(390,60.8,23.6)},turnInReference=true,objectiveReference=true,
   instructions="Accept this book at your faction's shrine, defeat every legendary beast named in this book using the guide's three regional circuits, then return and turn it in. Catching an ordinary wild version does not count."}
 end
end
